    fn each_reason_resolves_its_policy_from_the_scala_file() {
        use LimitedActionType as T;
        let community_unavailable = vec![
            T::AddToBookmarks,
            T::AddToMoment,
            T::Embed,
            T::Follow,
            T::HideCommunityTweet,
            T::Like,
            T::ListsAddRemove,
            T::MuteConversation,
